// ── Helpers ───────────────────────────────────────────────────────────────
function today() { return new Date().toISOString().split("T")[0]; }
function nowTime() { return new Date().toTimeString().slice(0,5); }
function fmtDate(d) { return new Date(d+"T00:00:00").toLocaleDateString("fr-FR",{weekday:"long",day:"numeric",month:"long",year:"numeric"}); }
function fmtPlate(raw) {
  const v = raw.replace(/[^A-Z0-9]/gi,"").toUpperCase().slice(0,7);
  if (v.length<=2) return v;
  if (v.length<=5) return v.slice(0,2)+"-"+v.slice(2);
  return v.slice(0,2)+"-"+v.slice(2,5)+"-"+v.slice(5,7);
}
function calcDist(pts) {
  if (!pts||pts.length<2) return 0;
  let d=0;
  for(let i=1;i<pts.length;i++){
    const R=6371,dLat=(pts[i].lat-pts[i-1].lat)*Math.PI/180,dLon=(pts[i].lng-pts[i-1].lng)*Math.PI/180;
    const a=Math.sin(dLat/2)**2+Math.cos(pts[i-1].lat*Math.PI/180)*Math.cos(pts[i].lat*Math.PI/180)*Math.sin(dLon/2)**2;
    d+=R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));
  }
  return Math.round(d*10)/10;
}
function totalKm(m) { const d=parseInt(m.kmDeparture)||0,r=parseInt(m.kmReturn)||0; return r>d?r-d:0; }
function getEmptyForm() {
  return {
    id:null, date:today(), name:"", vehicleId:"", status:"planned",
    timeDeparture:"", kmDeparture:"",
    pickupAddresses:[""], dropAddresses:[""],
    departureAddress:"", returnAddress:"",
    timeReturn:"", kmReturn:"",
    observations:"", photos:[], gpsTrack:[], stops:[],
  };
}

