// ── AddressesView ─────────────────────────────────────────────────────────
const AddressesView = React.memo(function AddressesView({ savedAddresses, userId, showToast }) {
  const [newAddr, setNewAddr] = useState({ label: "", address: "" });
  const [editId, setEditId] = useState(null);
  const [editData, setEditData] = useState({ label: "", address: "" });

  async function addAddress() {
    if (!newAddr.label.trim() || !newAddr.address.trim()) { showToast("⚠️ Libellé et adresse requis"); return; }
    const id = String(Date.now());
    await setDoc(doc(db, "addresses", id), { id, ...newAddr, userId });
    setNewAddr({ label: "", address: "" });
    showToast("✅ Adresse enregistrée !");
  }

  async function deleteAddress(id) {
    await deleteDoc(doc(db, "addresses", id));
    showToast("🗑️ Adresse supprimée");
  }

  async function saveEdit(id) {
    await setDoc(doc(db, "addresses", id), { id, ...editData, userId });
    setEditId(null);
    showToast("✅ Adresse modifiée");
  }

  return (
    <div>
      <div className="page-title">📍 Mes adresses</div>

      {savedAddresses.length === 0 ? (
        <div className="empty">
          <div style={{fontSize:40,marginBottom:8}}>📍</div>
          <div style={{fontSize:13}}>Aucune adresse enregistrée</div>
          <div style={{fontSize:11,color:"var(--muted)",marginTop:6}}>Ajoutez vos adresses fréquentes pour les réutiliser dans vos missions</div>
        </div>
      ) : (
        <div className="card">
          {savedAddresses.map(a => (
            <div key={a.id} style={{padding:"12px 0",borderBottom:"1px solid var(--border)"}}>
              {editId === a.id ? (
                <div>
                  <div className="field" style={{marginBottom:8}}>
                    <input type="text" className="input" placeholder="Libellé" value={editData.label}
                      onChange={e => setEditData(d => ({...d, label: e.target.value}))}/>
                  </div>
                  <div className="field" style={{marginBottom:8}}>
                    <input type="text" className="input" placeholder="Adresse complète" value={editData.address}
                      onChange={e => setEditData(d => ({...d, address: e.target.value}))}/>
                  </div>
                  <div style={{display:"flex",gap:8}}>
                    <button className="btn btn-secondary btn-sm" onClick={() => setEditId(null)}>Annuler</button>
                    <button className="btn btn-success btn-sm" onClick={() => saveEdit(a.id)}>✅ Sauvegarder</button>
                  </div>
                </div>
              ) : (
                <div style={{display:"flex",alignItems:"center",gap:10}}>
                  <div style={{fontSize:22}}>📍</div>
                  <div style={{flex:1}}>
                    <div style={{fontFamily:"Montserrat",fontWeight:700,fontSize:14,color:"var(--orange2)"}}>{a.label}</div>
                    <div style={{fontSize:12,color:"var(--muted)",marginTop:2}}>{a.address}</div>
                  </div>
                  {a.userId === userId && (
                    <div style={{display:"flex",gap:6}}>
                      <button className="btn btn-secondary btn-sm" onClick={() => { setEditId(a.id); setEditData({label:a.label,address:a.address}); }}>✏️</button>
                      <button className="btn btn-danger btn-sm" onClick={() => { if(confirm("Supprimer ?")) deleteAddress(a.id); }}>🗑️</button>
                    </div>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      <div className="card">
        <div className="card-title">+ Ajouter une adresse</div>
        <div className="field">
          <label className="label">Libellé (nom court)</label>
          <input type="text" className="input" placeholder="Ex: Dépôt principal, Mairie de Lyon..."
            value={newAddr.label} onChange={e => setNewAddr(n => ({...n, label: e.target.value}))}/>
        </div>
        <div className="field">
          <label className="label">Adresse complète</label>
          <div style={{display:"flex",gap:8}}>
            <input type="text" className="input" placeholder="Ex: 15 rue de la Paix, Paris"
              value={newAddr.address} onChange={e => setNewAddr(n => ({...n, address: e.target.value}))} style={{flex:1}}/>
            <button className="btn btn-secondary btn-sm" style={{flexShrink:0}} onClick={async () => {
              if (!navigator.geolocation) { showToast("GPS non disponible"); return; }
              showToast("📍 Localisation...");
              navigator.geolocation.getCurrentPosition(async pos => {
                try {
                  const r = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${pos.coords.latitude}&lon=${pos.coords.longitude}`);
                  const d = await r.json();
                  const addr = d.display_name || `${pos.coords.latitude.toFixed(5)}, ${pos.coords.longitude.toFixed(5)}`;
                  setNewAddr(n => ({...n, address: addr}));
                  showToast("📍 Position capturée !");
                } catch {
                  setNewAddr(n => ({...n, address: `${pos.coords.latitude.toFixed(5)}, ${pos.coords.longitude.toFixed(5)}`}));
                }
              }, () => showToast("❌ GPS non disponible"), {enableHighAccuracy:true});
            }}>📍</button>
          </div>
        </div>
        <AddressMapPicker onPick={addr => setNewAddr(n => ({...n, address: addr}))} />
        <button className="btn btn-primary btn-full" onClick={addAddress}>Ajouter l'adresse</button>
      </div>
    </div>
  );
});

// ── RoutePreviewMap ───────────────────────────────────────────────────────
const RoutePreviewMap = React.memo(function RoutePreviewMap({ addresses }) {
  const mapRef = useRef(null);
  const mapObj = useRef(null);
  const markersRef = useRef([]);
  const routeRef = useRef(null);
  const debounceRef = useRef(null);

  useEffect(() => {
    // Init map once
    function initMap() {
      if (!mapRef.current || !window.L || mapObj.current) return;
      mapObj.current = window.L.map(mapRef.current, {
        zoomControl: true, attributionControl: false,
        center: [46.6, 2.3], zoom: 5
      });
      window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19 }).addTo(mapObj.current);
    }
    if (window.L) initMap();
    else setTimeout(initMap, 800);
  }, []);

  useEffect(() => {
    // Debounce address changes to avoid too many requests
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => updateRoute(), 1200);
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [addresses]);

  async function updateRoute() {
    if (!mapObj.current || !window.L) return;
    const valid = addresses.filter(a => a && a.trim().length > 4);
    if (valid.length === 0) return;

    // Clear previous markers and route
    markersRef.current.forEach(m => { try { m.remove(); } catch(e) {} });
    markersRef.current = [];
    if (routeRef.current) { try { routeRef.current.remove(); } catch(e) {} routeRef.current = null; }

    // Geocode addresses
    const colors = ['#2ecc71', '#f5a623', '#f5a623', '#f5a623', '#3498db', '#3498db', '#e74c3c'];
    const emojis = ['🟢', '🟡', '🟡', '🟡', '🔵', '🔵', '🔴'];
    const coords = [];
    for (let i = 0; i < valid.length; i++) {
      try {
        const r = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(valid[i])}&limit=1&countrycodes=fr`);
        const d = await r.json();
        if (d.length > 0) {
          const lat = parseFloat(d[0].lat), lng = parseFloat(d[0].lon);
          coords.push([lat, lng]);
          const color = colors[Math.min(i, colors.length-1)];
          const marker = window.L.circleMarker([lat, lng], {
            radius: 10, fillColor: color, color: 'white', weight: 2, fillOpacity: 1
          }).bindTooltip(valid[i], { permanent: false, direction: 'top' }).addTo(mapObj.current);
          markersRef.current.push(marker);
        }
      } catch(e) {}
    }

    if (coords.length === 0) return;

    // Fit map to markers
    if (coords.length === 1) {
      mapObj.current.setView(coords[0], 13);
    } else {
      const bounds = window.L.latLngBounds(coords);
      mapObj.current.fitBounds(bounds, { padding: [30, 30] });
    }

    // Draw route if 2+ points
    if (coords.length >= 2) {
      try {
        const coordStr = coords.map(c => `${c[1]},${c[0]}`).join(';');
        const r = await fetch(`https://router.project-osrm.org/route/v1/driving/${coordStr}?overview=full&geometries=geojson`);
        const d = await r.json();
        if (d.routes?.[0]) {
          const latlngs = d.routes[0].geometry.coordinates.map(c => [c[1], c[0]]);
          routeRef.current = window.L.polyline(latlngs, {
            color: '#f5a623', weight: 4, opacity: 0.8
          }).addTo(mapObj.current);
          mapObj.current.fitBounds(routeRef.current.getBounds(), { padding: [30, 30] });
        }
      } catch(e) {}
    }
  }

  return (
    <div style={{ marginBottom: 14 }}>
      <label className="label">🗺️ Aperçu de l'itinéraire</label>
      <div ref={mapRef} style={{
        width: '100%', height: 220, borderRadius: 12,
        overflow: 'hidden', border: '1px solid var(--border)',
        background: '#1a0a0a'
      }}/>
      <div style={{ fontSize: 10, color: 'var(--muted)', marginTop: 4 }}>
        🟢 Départ &nbsp;🟡 Prise en charge &nbsp;🔵 Dépose &nbsp;🔴 Retour — Se met à jour automatiquement
      </div>
    </div>
  );
});

