  // ── Calendar ────────────────────────────────────────────────────────────
  function CalendarView() {
    const year=calDate.getFullYear(), month=calDate.getMonth();
    const first=new Date(year,month,1).getDay();
    const dim=new Date(year,month+1,0).getDate();
    const doneDays=new Set(missions.filter(m=>m.status==="done").map(m=>m.date));
    const plannedDays=new Set(missions.filter(m=>m.status!=="done").map(m=>m.date));
    const days=[]; const off=first===0?6:first-1;
    for(let i=0;i<off;i++) days.push(null);
    for(let d=1;d<=dim;d++) days.push(d);
    function ds(d){return `${year}-${String(month+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`;}
    return (
      <div>
        <div className="cal-nav">
          <button className="cal-nav-btn" onClick={()=>setCalDate(new Date(year,month-1))}>‹</button>
          <span className="cal-month">{calDate.toLocaleDateString("fr-FR",{month:"long",year:"numeric"})}</span>
          <button className="cal-nav-btn" onClick={()=>setCalDate(new Date(year,month+1))}>›</button>
        </div>
        <div className="cal-grid">
          {["Lu","Ma","Me","Je","Ve","Sa","Di"].map(d=><div key={d} className="cal-hdr">{d}</div>)}
          {days.map((d,i)=>(
            <div key={i} className={"cal-day"+(d?"":" empty")+(d&&ds(d)===todayStr?" today":"")+(d&&(doneDays.has(ds(d))||plannedDays.has(ds(d)))?" has-mission":"")+(d&&ds(d)===selectedDay?" selected":"")}
              onClick={()=>d&&setSelectedDay(ds(d))}>{d}</div>
          ))}
        </div>
        <div className="section-divider"><span>{selectedDay===todayStr?"Aujourd'hui":fmtDate(selectedDay).split(" ").slice(0,2).join(" ")}</span></div>
        {dayMissions.length===0 ? (
          <div className="empty">
            <div style={{fontSize:40,marginBottom:8}}>🚌</div>
            <div style={{fontSize:13}}>Aucune mission ce jour</div><br/>
            <button className="btn btn-primary btn-sm" onClick={()=>{setForm({...getEmptyForm(),date:selectedDay});setView("form");}}>+ Nouvelle mission</button>
          </div>
        ) : dayMissions.map(m=><MissionCard key={m.id} m={m} vehicles={vehicles} onSelect={handleSelectMission}/>)}
      </div>
    );
  }

